/*
 * A121176  Union of {8, 9, 18}, S, 2S and 4S, where S = squarefree numbers
 *          (A005117).
 * https://oeis.org/A121176
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n-th smallest integer of the set {8,9,18} ∪ S ∪ 2S ∪ 4S,
 *            where S is the set of square‑free integers. The sequence is
 *            generated by testing each integer for membership in that set
 *            until n terms have been collected
 * Range:     u8 n <= 198, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* Autogenerated helpers */
#include "../utils/seq_realloc.h"

/* Check whether an integer is square‑free. */
static bool is_squarefree(idx_t n)
{
    if (n <= 1) return true;          /* 1 is square‑free */
    idx_t tmp = n;
    for (idx_t p = 2; p <= tmp / p; ++p) {
        if (tmp % p == 0) {
            tmp /= p;
            if (tmp % p == 0)       /* a square factor found */
                return false;
        }
    }
    return true;
}

/* Test membership in {8,9,18} ∪ S ∪ 2S ∪ 4S. */
static bool in_union(idx_t m)
{
    if (m == 8 || m == 9 || m == 18) return true;
    if (is_squarefree(m))           return true;
    if ((m & 1) == 0 && is_squarefree(m >> 1)) return true;
    if ((m & 3) == 0 && is_squarefree(m >> 2)) return true;
    return false;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    static seq_t *cache   = NULL;
    static size_t cache_len = 0;
    static size_t cache_cap = 0;
    static idx_t last_checked = 0;

    /* Grow the cache until it contains at least n entries */
    while (cache_len < n) {
        ++last_checked;
        if (in_union(last_checked)) {
            if (cache_len == cache_cap) {
                size_t new_cap = cache_cap ? cache_cap << 1 : 16;
                seq_t *tmp = seq_realloc(cache, cache_cap, new_cap);
                if (!tmp) { exit(EXIT_FAILURE); }
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = (seq_t)last_checked;
        }
    }

    return cache[n - 1];
}
